-- Constraint attribute lists and their positioned errors, column constraints
-- added with ALTER TABLE ... ADD COLUMN, keys rejected on foreign tables,
-- identity columns on foreign tables, and index-build conflict errors.
CREATE TABLE r218 (a int PRIMARY KEY);
CREATE TABLE c218 (a int, CHECK (a > 0) DEFERRABLE);
CREATE TABLE c218 (a int, CHECK (a > 0) DEFERRABLE NOT DEFERRABLE);
CREATE TABLE c218 (a int, UNIQUE (a) NOT DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE c218 (a int, UNIQUE (a) NO INHERIT);
CREATE TABLE c218 (a int, PRIMARY KEY (a) NOT ENFORCED);
CREATE TABLE c218 (a int, CHECK (a > 0) NOT VALID NO INHERIT NOT ENFORCED DEFERRABLE);
CREATE TABLE c218 (a int, EXCLUDE USING gist (a WITH &&) NOT VALID);
CREATE TABLE c218 (a int REFERENCES r218 NOT DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE c218 (a int REFERENCES r218 INITIALLY DEFERRED NOT DEFERRABLE);
CREATE TABLE c218 (a int REFERENCES r218 ENFORCED ENFORCED);
CREATE TABLE c218 (a int REFERENCES r218 DEFERRABLE DEFERRABLE);
CREATE TABLE c218 (a int REFERENCES r218 NOT VALID);
CREATE TABLE c218 (a int CHECK (a > 0) INITIALLY IMMEDIATE);
CREATE TABLE c218 (a int NOT NULL DEFERRABLE);
CREATE TABLE c218 (a int DEFERRABLE);
CREATE TABLE c218 (a int UNIQUE NOT ENFORCED);
CREATE TABLE c218 (a int CHECK (a > 0) NOT VALID);
CREATE TABLE c218 (a int UNIQUE INITIALLY DEFERRED, b int REFERENCES r218 INITIALLY DEFERRED DEFERRABLE,
  c int CHECK (c > 0) NOT ENFORCED, CHECK (a > 0) NOT VALID, FOREIGN KEY (a) REFERENCES r218 NOT VALID);
SELECT conname, contype, condeferrable, condeferred, conenforced, convalidated, connoinherit
  FROM pg_constraint WHERE conrelid = 'c218'::regclass ORDER BY conname;
ALTER TABLE c218 ADD CONSTRAINT q218 UNIQUE (a) NOT VALID;
ALTER TABLE c218 ADD CHECK (a > 1) DEFERRABLE;
ALTER TABLE c218 ADD CHECK (a > 1) NOT VALID;
SELECT conname, convalidated FROM pg_constraint WHERE conrelid = 'c218'::regclass AND contype = 'c' ORDER BY conname;
CREATE TABLE t218 (a int, r int4range);
INSERT INTO t218 VALUES (1, '[1,3)'), (1, '[2,4)');
ALTER TABLE t218 ADD COLUMN b int PRIMARY KEY;
ALTER TABLE t218 ADD COLUMN b int UNIQUE;
ALTER TABLE t218 ADD COLUMN c int DEFAULT 5 UNIQUE;
ALTER TABLE t218 ADD COLUMN c int REFERENCES r218, ADD COLUMN d int CHECK (d > 0) CONSTRAINT dd218 NOT NULL;
ALTER TABLE t218 ADD COLUMN d int CHECK (d > 0) NOT VALID;
ALTER TABLE t218 ADD COLUMN e int CONSTRAINT ek218 UNIQUE DEFERRABLE INITIALLY DEFERRED, ADD COLUMN f int CONSTRAINT fk218 REFERENCES r218 NOT ENFORCED;
ALTER TABLE t218 ADD UNIQUE (a);
ALTER TABLE t218 ADD CONSTRAINT x218 EXCLUDE USING gist (r WITH &&);
ALTER TABLE t218 ADD EXCLUDE USING gist (a WITH =);
CREATE UNIQUE INDEX i218 ON t218 (a);
SELECT conname, contype, condeferrable, condeferred, conenforced, convalidated, conkey
  FROM pg_constraint WHERE conrelid = 't218'::regclass ORDER BY conname;
CREATE FOREIGN DATA WRAPPER w218;
CREATE SERVER s218 FOREIGN DATA WRAPPER w218;
CREATE FOREIGN TABLE f218 (a int UNIQUE) SERVER s218;
CREATE FOREIGN TABLE f218 (a int PRIMARY KEY) SERVER s218;
CREATE FOREIGN TABLE f218 (a int REFERENCES r218) SERVER s218;
CREATE FOREIGN TABLE f218 (a int, UNIQUE (a)) SERVER s218;
CREATE FOREIGN TABLE f218 (a int, PRIMARY KEY (a)) SERVER s218;
CREATE FOREIGN TABLE f218 (a int, FOREIGN KEY (a) REFERENCES r218) SERVER s218;
CREATE FOREIGN TABLE f218 (a int, EXCLUDE USING gist (a WITH &&)) SERVER s218;
CREATE FOREIGN TABLE f218 (a int CONSTRAINT nm218 UNIQUE DEFERRABLE) SERVER s218;
CREATE FOREIGN TABLE f218 (a int CHECK (a > 0), b int REFERENCES r218, c int UNIQUE) SERVER no_such_server;
CREATE FOREIGN TABLE f218 (a int GENERATED ALWAYS AS IDENTITY, b int NOT NULL, c int CHECK (c > 0), d int DEFAULT 1) SERVER s218;
SELECT attname, attidentity, attnotnull FROM pg_attribute WHERE attrelid = 'f218'::regclass AND attnum > 0 ORDER BY attnum;
CREATE FOREIGN TABLE g218 (a int, CHECK (a > 0) NOT VALID) SERVER s218;
SELECT conname, convalidated FROM pg_constraint WHERE conrelid = 'g218'::regclass;
ALTER FOREIGN TABLE g218 ADD CONSTRAINT u218 UNIQUE (a);
ALTER TABLE g218 ADD PRIMARY KEY (a);
ALTER TABLE g218 ADD FOREIGN KEY (a) REFERENCES r218;
ALTER TABLE g218 ADD COLUMN z int UNIQUE;
ALTER TABLE g218 ADD COLUMN y int PRIMARY KEY;
ALTER TABLE g218 ADD COLUMN x int REFERENCES r218;
ALTER TABLE g218 ADD COLUMN w int GENERATED ALWAYS AS IDENTITY;
SELECT conname FROM pg_constraint WHERE conrelid = 'g218'::regclass ORDER BY conname;
SELECT * FROM g218;
INSERT INTO g218 (a) VALUES (1);
DROP FOREIGN TABLE f218, g218;
DROP SERVER s218;
